<script lang="ts">import type{DeliveryOrder}from"./types";let{orders,onOpen}:{orders:DeliveryOrder[];onOpen:(o:DeliveryOrder)=>void}=$props();const label=(o:DeliveryOrder)=>o.state==="new"?"Novo":o.state==="preparing"?`${o.items.filter(i=>i.checked).length}/${o.items.length} conferidos`:"Pronto para retirada";</script>
<section class="rail" aria-label="Pedidos conectados"><header><strong>Pedidos conectados</strong><small>A venda local continua livre</small></header><div>{#each orders.filter(o=>o.state!=="collected") as order}<button onclick={()=>onOpen(order)} class:ready={order.state==="ready"}><span>{order.provider}</span><b>#{order.id}</b><small>{label(order)} · {order.elapsed}</small></button>{/each}</div></section>
<style>.rail{background:#092e34;color:#f2e9d8;padding:10px 14px;display:grid;grid-template-columns:155px minmax(0,1fr);gap:12px;align-items:center;border-bottom:1px solid #31595a}.rail header strong,.rail header small{display:block}.rail header strong{font:700 13px "Space Grotesk"}.rail header small{font-size:9px;color:#a9c1ba;margin-top:3px}.rail>div{display:flex;gap:8px;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin;scrollbar-color:#d79f34 #d8e2d9}.rail button{flex:0 0 145px;min-width:0;padding:9px 10px;text-align:left;border:1px solid #50746b;background:#17483d;color:#f3ead7;cursor:pointer}.rail button.ready{border-color:#e7a83a}.rail span,.rail b,.rail button small{display:block}.rail span{font-size:10px;color:#c1d5ce}.rail b{font:700 14px "Space Grotesk"}.rail button small{font-size:9px;color:#d7e3dd;margin-top:3px}.rail>div::-webkit-scrollbar{height:7px}.rail>div::-webkit-scrollbar-track{background:#d8e2d9}.rail>div::-webkit-scrollbar-thumb{background:#d79f34;border:1px solid #d8e2d9}</style>
